/*
 * initramfs_data.S - Embedded initramfs data
 *
 * This file includes the initramfs CPIO archive as binary data.
 * The archive is generated by scripts/mkinitramfs.sh
 */

.section .rodata
.global _binary_initramfs_cpio_start
.global _binary_initramfs_cpio_end

_binary_initramfs_cpio_start:
#ifdef EMBED_INITRAMFS
    .incbin "initramfs.cpio"
#endif
_binary_initramfs_cpio_end:
